import{_ as e,c as o,o as r,ae as a}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Table Settings","description":"Table Settings","frontmatter":{"title":"Table Settings","description":"Table Settings"},"headers":[],"relativePath":"guide/drag-drop-settings/ninja-tables-drag-and-drop-table-settings.md","filePath":"guide/drag-drop-settings/ninja-tables-drag-and-drop-table-settings.md"}'),n={name:"guide/drag-drop-settings/ninja-tables-drag-and-drop-table-settings.md"};function d(s,t,l,i,c,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="table-settings" tabindex="-1">Table Settings <a class="header-anchor" href="#table-settings" aria-label="Permalink to &quot;Table Settings&quot;">​</a></h1><p>You already know Ninja Tables is a great WordPress table builder plugin. This plugin has tons of features that you can use to impress your audience. In this document, we will discuss the table settings and customization options and see what they can do. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Data-Table-Settings-1024x688.png" alt="Data Table Settings"></p><h2 id="properties-of-table-settings" tabindex="-1"><strong>Properties of Table Settings</strong> <a class="header-anchor" href="#properties-of-table-settings" aria-label="Permalink to &quot;**Properties of Table Settings**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Cell Padding</td><td>Numeric Value</td></tr><tr><td></td><td>Table Alignment</td><td>Left, Center, and Right</td></tr><tr><td></td><td>Separate Column/Rows</td><td>Toggle On or Off</td></tr><tr><td></td><td>Space Between Columns</td><td>Numeric Value</td></tr><tr><td></td><td>Space Between Rows</td><td>Numeric Value</td></tr><tr><td></td><td>Table Container Max Width</td><td>Toggle On or Off</td></tr><tr><td></td><td>Table Cell Min Auto Width</td><td>Numeric Value</td></tr><tr><td></td><td>Table Container Max Height</td><td>Numeric Value</td></tr><tr><td><strong>Background</strong></td><td>Header Background</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Even Row Background</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Odd Row Background</td><td>Graphical Color Selection</td></tr><tr><td><strong>Custom CSS</strong></td><td>Add custom CSS</td><td></td></tr><tr><td><strong>Custom JS</strong></td><td>Add custom JS</td><td></td></tr><tr><td><strong>Sticky</strong></td><td>First Row Sticky</td><td>Toggle On or Off</td></tr><tr><td></td><td>First Column Sticky</td><td>Toggle On or Off</td></tr><tr><td><strong>Accessibility</strong></td><td>Table Role</td><td>Dropdown Selection</td></tr><tr><td><strong>Border</strong></td><td>Table Border</td><td>Numeric Value</td></tr><tr><td></td><td>Border Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Apply Inner Border</td><td>Toggle On or Off</td></tr><tr><td></td><td>Header Inner Border</td><td>Toggle On or Off</td></tr><tr><td></td><td>Inner Border Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Inner Border Size</td><td>Numeric Value</td></tr><tr><td><strong>Global Style</strong></td><td>Margin Top</td><td>Numeric Value</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value</td></tr><tr><td></td><td>Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Family</td><td>Dropdown Selection</td></tr><tr><td><strong>Export Table</strong></td><td>Select Format</td><td>Dropdown Selection</td></tr></tbody></table><h3 id="general" tabindex="-1"><strong>General</strong> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;**General**&quot;">​</a></h3><p><strong>Cell Padding:</strong> Cell padding controls the space between the element and the cell area. By default, it is set to 10. <strong>Table Alignment:</strong> You can align the whole table on the page&#39;s left, Center, or Right side. <strong>Separate Columns</strong>/<strong>Rows</strong>: You can also separate the rows or columns. By default, it is set to “Off.” <strong>Space Between Columns:</strong> Customize the spaces between columns to display cells as single blocks. <strong>Space Between Rows:</strong> Customize the spaces between rows to display cells as single blocks. <strong>Table Container Max Width:</strong> Control the maximum width of the table. If the maximum width is lower than the table content, then you will notice a bottom scrollbar to scroll through the data. **Table Cell Min Auto Width: **Control the table cell width. <strong>Table Container Max Height:</strong> Control the table cell height. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Table-cell-settings-1024x479.png" alt="Table cell settings"></p><h3 id="background" tabindex="-1"><strong>Background</strong> <a class="header-anchor" href="#background" aria-label="Permalink to &quot;**Background**&quot;">​</a></h3><p><strong>Header Background:</strong> You can control the header background color from here without going to Background management. <strong>Even Row Background:</strong> This option is to control the Even Row background color. <strong>Odd Row Background:</strong> This is used to set the background color for even rows. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Table-header-background-1024x564.png" alt="Table header background"></p><h3 id="custom-css-pro" tabindex="-1">Custom CSS (Pro) <a class="header-anchor" href="#custom-css-pro" aria-label="Permalink to &quot;Custom CSS (Pro)&quot;">​</a></h3><p>Just like the Ninja Tables advanced mode, the Drag and Drop table builder gives you the flexibility to customize tables with custom CSS. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Custom-CSS-in-drag-and-drop-1024x500.png" alt="Custom CSS in drag and drop"></p><h3 id="custom-js-pro" tabindex="-1">Custom JS (Pro) <a class="header-anchor" href="#custom-js-pro" aria-label="Permalink to &quot;Custom JS (Pro)&quot;">​</a></h3><p>Similarly, the Drag and Drop table builder also gives you the flexibility to further customize tables with custom JS. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Custom-JS-drag-and-drop-1024x530.png" alt="Custom JS drag and drop"></p><h3 id="sticky-pro" tabindex="-1">Sticky (Pro) <a class="header-anchor" href="#sticky-pro" aria-label="Permalink to &quot;Sticky (Pro)&quot;">​</a></h3><p><strong>First Row Sticky:</strong> You can freeze the first row or make it sticky. If you have to scroll down, you can see which column contains which type of data. <strong>First Column Sticky:</strong> You can make the first column sticky as well. This helps if the table is horizontally scrollable.</p><h3 id="accessibility" tabindex="-1"><strong>Accessibility</strong> <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;**Accessibility**&quot;">​</a></h3><p><strong>Table Role:</strong> This option has 4 types of &quot;Table Role.&quot; <img src="https://ninjatables.com/wp-content/uploads/2023/08/table-roles-1024x616.png" alt="table roles"></p><ul><li>Table</li><li>Presentation</li><li>List</li><li>Row Group.</li></ul><h3 id="border" tabindex="-1"><strong>Border</strong> <a class="header-anchor" href="#border" aria-label="Permalink to &quot;**Border**&quot;">​</a></h3><p><strong>Table Border:</strong> This option enables you to show each cell with a border a boundary. By default, it is set to 2. <strong>Border Color:</strong> You can control the color of the border here. <strong>Apply Inner Border:</strong> By default, an Inner Border is applied to the table. <strong>Header Inner Border:</strong> You can also control whether the Header should have an inner border. <strong>Inner Border Color:</strong> The option to control the inner border color. <strong>Inner Border Size:</strong> You can also set the inner border size, which is by default set to 3. <img src="https://ninjatables.com/wp-content/uploads/2023/08/drag-and-drop-table-border-1024x574.png" alt="drag and drop table border"></p><h3 id="global-style" tabindex="-1"><strong>Global Styl</strong>e <a class="header-anchor" href="#global-style" aria-label="Permalink to &quot;**Global Styl**e&quot;">​</a></h3><p><strong>Margin Top:</strong> You can add an additional Top Margin to the table, which is set to 0 by default. <strong>Margin Bottom</strong>: You can add an additional Bottom Margin to the table, which is set to 0 by default. <strong>Font Size:</strong> The default font size setting is by default set to 15. <strong>Color:</strong> You can also define the font color that is set to black by default. <strong>Font Family:</strong> You can also select a Font Family for your table from the dropdown, and plenty of fonts are available. <img src="https://ninjatables.com/wp-content/uploads/2023/08/drag-and-drop-table-border-1024x574.png" alt="drag and drop table border"></p><h3 id="export-table" tabindex="-1">Export Table <a class="header-anchor" href="#export-table" aria-label="Permalink to &quot;Export Table&quot;">​</a></h3><p>One of the most important and helpful options that you can use to export your table to CSV and JSON format. The JSON format is only recognizable by Ninja Tables</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Customize the drag and drop table settings using all these amazing features and options. Let us know if you have any questions.</p>',25)])])}const b=e(n,[["render",d]]);export{u as __pageData,b as default};
